// Fasi del percorso: ogni esercizio della libreria ne ha una; nella scheda
// paziente e nella vista del paziente gli esercizi sono raggruppati in questo ordine.
export const exercisePhases = [
  { id: 'acuta', label: 'Fase acuta', hint: 'Proteggere la zona, calmare il dolore, muoversi in modo dolce' },
  { id: 'subacuta', label: 'Fase subacuta', hint: 'Recuperare mobilità e controllo, carico leggero e graduale' },
  { id: 'rinforzo', label: 'Fase di rinforzo', hint: 'Forza progressiva e resistenza al carico' },
  { id: 'ritorno', label: 'Ritorno all\'attività', hint: 'Gesti funzionali e sport-specifici, criteri di rientro' },
];

export function phaseLabel(id) {
  return exercisePhases.find((p) => p.id === id)?.label || null;
}

// Link YouTube generato in automatico dal nome dell'esercizio: apre i risultati
// di ricerca (sempre raggiungibili, mai un video rimosso). Per un video preciso
// basta incollare il suo link nelle note dell'esercizio: il link automatico sparisce.
export function exerciseVideoUrl(name) {
  return 'https://www.youtube.com/results?search_query=' + encodeURIComponent(name + ' esercizio fisioterapia');
}

// Dose di partenza di un esercizio: quella esplicita (nuove voci) oppure estratta
// dal testo ("3 serie da 10-12 ripetizioni", "tenuta 45 secondi"). E' solo un punto
// di partenza: serie, ripetizioni, carico e frequenza si modificano per ogni paziente.
export function exerciseDose(ex) {
  if (ex.dose) return { sets: ex.dose.sets || '', reps: ex.dose.reps || '', load: ex.dose.load || '', frequency: ex.dose.frequency || '' };
  const d = ex.description || '';
  const sets = (d.match(/(\d+(?:-\d+)?)\s+serie/i) || [])[1] || '';
  let reps = (d.match(/serie da (\d+(?:-\d+)*)\s+(?:ripetizioni|passi|saltelli|respiri)/i) || [])[1] || '';
  if (!reps) reps = (d.match(/(\d+(?:-\d+)*)\s+ripetizioni/i) || [])[1] || '';
  const hold = (d.match(/(?:tenere|mantenere|tenuta(?: di)?|per)\s+(\d+(?:-\d+)?)\s*(?:secondi|s\b|''|")/i) || [])[1];
  const freq = (d.match(/(\d+(?:-\d+)?\s+volte\s+(?:al giorno|a settimana))/i) || [])[1] || '';
  return { sets, reps, load: hold ? `tenuta ${hold} s` : '', frequency: freq };
}

// Aumenta di un passo un valore numerico o un intervallo ("3" -> "4", "10-12" -> "11-13").
export function bumpDose(value, delta = 1) {
  const v = String(value || '').trim();
  if (/^\d+$/.test(v)) return String(Math.max(0, Number(v) + delta));
  const m = v.match(/^(\d+)\s*-\s*(\d+)$/);
  if (m) return `${Math.max(0, Number(m[1]) + delta)}-${Math.max(0, Number(m[2]) + delta)}`;
  return v;
}
